declare namespace Gordic.Pam.Interface {
	/**Třída pro uložení access tokenu PAM = informací o objektu, zdali je jej možno editovat, rušit ....
	*     Důvodem vyčlenění mimo bázi je nutnost použití v TS
	*/
	interface GPamACT {
		/**Create - INSERT*/
		Create?: boolean|null;
		/**Read (Retrieve) - SELECT*/
		Read?: boolean|null;
		/**Update*/
		Update?: boolean|null;
		/**Upsert*/
		Upsert?: boolean|null;
		/**Delete*/
		Delete?: boolean|null;
	}
	const enum GPamACTNames { Create = "Create", Read = "Read", Update = "Update", Upsert = "Upsert", Delete = "Delete",}
	const enum GPamACTFragments { Create = "*", Read = "*", Update = "*", Upsert = "*", Delete = "*",}
	const enum GPamACTTypes { Create = "boolean", Read = "boolean", Update = "boolean", Upsert = "boolean", Delete = "boolean",}
	const enum GPamACTTypeLengths {}
}

//#endregion

